fn gc_clear(v: &V) {
    // Move the contents out first and drop them after the borrow is released: dropping a value can run code
    // (an Ext's Drop, a generator's finally), which must not happen while the container is still borrowed.
    match v {
        V::Obj(o) => {
            let mut hold: Vec<V> = vec![];
            {
                let mut d = o.d.borrow_mut();
                for (_, x) in d.iter_mut() {
                    hold.push(std::mem::replace(x, V::None));
                }
            }
            let inner = o.inner.borrow_mut().take();
            if let Some(x) = inner {
                hold.push(x);
            }
            drop(hold);
        }
        V::List(l) => drop(std::mem::take(&mut *l.borrow_mut())),
        V::Dict(d) => drop(std::mem::replace(&mut *d.borrow_mut(), Dict::new())),
        V::Set(s) => drop(std::mem::replace(&mut *s.borrow_mut(), PSet::new())),
        V::Deque(d) => drop(std::mem::take(&mut d.borrow_mut().v)),
        V::Iter(it) => drop(std::mem::replace(&mut *it.borrow_mut(), It::Done)),
        _ => {}
    }
}

